import{ABILITY_TRIGGERS,ABILITY_CONDITIONS,ABILITY_EFFECTS}from'./creature-model.js';
import{validateNativeAbility}from'./ability-native.js';
export function validateAbilityStudio(project){const s=project.abilityStudio;if(s===undefined)return;if(!s||s.version!==1||!Array.isArray(s.abilities)||s.abilities.length>128)throw Error('Invalid ability library.');const ids=new Set();for(const a of s.abilities){if(!a||typeof a.id!=='string'||ids.has(a.id)||typeof a.name!=='string'||!a.name.trim()||a.name.length>40||typeof(a.description??'')!=='string'||(a.description||'').length>1024||!Array.isArray(a.rules)||a.rules.length>32)throw Error('Invalid ability definition.');ids.add(a.id);for(const r of a.rules)if(!r||!ABILITY_TRIGGERS.includes(r.when)||!ABILITY_CONDITIONS.includes(r.condition)||!ABILITY_EFFECTS.includes(r.effect)||!['self','ally','enemy','field'].includes(r.target||'self')||!Number.isFinite(r.value)||Math.abs(r.value)>10000||typeof(r.parameter??'')!=='string'||(r.parameter||'').length>80)throw Error('Invalid ability rule.');validateNativeAbility(a);}if(s.nativeIds!==undefined){if(!s.nativeIds||Array.isArray(s.nativeIds)||JSON.stringify(s.nativeIds).length>1000000)throw Error('Invalid ability ID registry.');for(const [hash,rows]of Object.entries(s.nativeIds)){if(!/^[a-f0-9]{64}$/.test(hash)||!rows||Array.isArray(rows))throw Error('Invalid ability source registry.');const used=new Set();for(const[id,value]of Object.entries(rows)){if(!/^[A-Za-z0-9:_-]{1,100}$/.test(id)||!Number.isInteger(value)||value<390||value>1023||used.has(value))throw Error('Invalid or duplicate ability ID reservation.');used.add(value);}}}return s;}
